use rust_differential_product_core::{generic::{Runtime,Mutation},schema::{Schema,Catalog,Manifest,Topic}};
use serde_json::{json,Value};
fn fixture()->(Runtime,String){let s=Schema::new(serde_json::from_value(json!({"format":1,"id":"all","version":1,"key":"id","fields":[{"name":"id","kind":"string","optional":false,"nullable":false},{"name":"v","kind":"uint64","optional":false,"nullable":false},{"name":"g","kind":"string","optional":false,"nullable":false}]})).unwrap()).unwrap();let fp=s.fingerprint().to_string();(Runtime::new(Catalog::new(Manifest{format:1,schemas:vec![s.definition().clone()],topics:vec![Topic{topic:"all".into(),schema:fp.clone()}]}).unwrap(),100).unwrap(),fp)}
fn query()->Value{json!({"global":true,"aggregates":{"n":{"aggFunc":"count"},"d":{"aggFunc":"countDistinct","field":"v"},"s":{"aggFunc":"sum","field":"v"},"a":{"aggFunc":"avg","field":"v"},"lo":{"aggFunc":"min","field":"v"},"hi":{"aggFunc":"max","field":"v"}},"order_by":[]})}
#[test]fn global_empty_stable_identity_exact_having_incremental_and_recovery(){let(mut r,fp)=fixture();r.open("q","all",&fp,serde_json::from_value(query()).unwrap()).unwrap();let empty=r.read("q",0,10,65536).unwrap();assert_eq!(empty.total_rows,1);assert!(empty.keys[0].starts_with("global1:"));assert_eq!(empty.rows,vec![json!({"n":"0","d":"0","s":"0","a":null,"lo":null,"hi":null})]);let id=empty.keys[0].clone();let mut h=query();h["having"]=json!({"op":"gt","field":"s","value":"18446744073709551615"});r.open("h","all",&fp,serde_json::from_value(h).unwrap()).unwrap();assert_eq!(r.read("h",0,10,65536).unwrap().total_rows,0);
for k in ["x","y"]{r.apply_committed("all",&fp,&[Mutation::Upsert{row:json!({"id":k,"v":"18446744073709551615","g":"A"})}]).unwrap();}let got=r.read("h",0,10,65536).unwrap();assert_eq!(got.keys,vec![id.clone()]);assert_eq!(got.rows[0]["s"],"36893488147419103230");assert_eq!(got.rows[0]["a"],"18446744073709551615");assert_eq!(r.metrics()["seed_rows"],0);r.apply_committed("all",&fp,&[Mutation::Delete{key:"x".into()},Mutation::Delete{key:"y".into()}]).unwrap();assert_eq!(r.read("h",0,10,65536).unwrap().total_rows,0);assert_eq!(r.read("q",0,10,65536).unwrap().keys,vec![id.clone()]);assert_eq!(r.read("q",0,10,65536).unwrap().rows,empty.rows);let(mut restored,fp)=fixture();restored.open("q","all",&fp,serde_json::from_value(query()).unwrap()).unwrap();assert_eq!(restored.read("q",0,10,65536).unwrap().keys,vec![id]);}
#[test]fn grouped_having_and_invalid_replacement(){let(mut r,fp)=fixture();let mut q=query();q.as_object_mut().unwrap().remove("global");q["group_by"]=json!(["g"]);q["having"]=json!({"op":"and","clauses":[{"op":"startsWith","field":"g","value":"A"},{"op":"ge","field":"n","value":"2"}]});r.open("q","all",&fp,serde_json::from_value(q.clone()).unwrap()).unwrap();for k in ["x","y"]{r.apply_committed("all",&fp,&[Mutation::Upsert{row:json!({"id":k,"v":"2","g":"A"})}]).unwrap();}assert_eq!(r.read("q",0,10,65536).unwrap().total_rows,1);for having in [json!({"op":"eq","field":"id","value":"x"}),json!({"op":"is_null","field":"n"}),json!({"op":"contains","field":"s","value":"1"}),json!({"op":"eq","field":"n","value":"-1"})]{let mut bad=q.clone();bad["having"]=having;assert!(r.open("q","all",&fp,serde_json::from_value(bad).unwrap()).is_err());assert_eq!(r.read("q",0,10,65536).unwrap().total_rows,1);}r.apply_committed("all",&fp,&[Mutation::Delete{key:"x".into()}]).unwrap();assert_eq!(r.read("q",0,10,65536).unwrap().total_rows,0);}
#[test]fn filtered_empty_null_having_pagination_and_alias_bounds(){let(mut r,fp)=fixture();r.apply_committed("all",&fp,&[Mutation::Upsert{row:json!({"id":"x","v":"3","g":"B"})}]).unwrap();let mut q=query();q["where"]=json!({"op":"contains","field":"g","value":"absent"});q["having"]=json!({"op":"is_null","field":"a"});r.open("q","all",&fp,serde_json::from_value(q.clone()).unwrap()).unwrap();assert_eq!(r.read("q",1,10,65536).unwrap().total_rows,1);assert!(r.read("q",1,10,65536).unwrap().rows.is_empty());assert_eq!(r.read("q",0,10,65536).unwrap().rows[0]["n"],"0");for change in [json!({"global":false,"aggregates":{"n":{"aggFunc":"count"}},"order_by":[]}),json!({"global":true,"group_by":[],"aggregates":{"n":{"aggFunc":"count"}},"order_by":[]}),json!({"select":["id"],"having":{"op":"is_value","field":"id"},"order_by":[]})]{assert!(r.open("q","all",&fp,serde_json::from_value(change).unwrap()).is_err());}let mut bad=q;bad["aggregates"]["rowId"]=json!({"aggFunc":"count"});assert!(r.open("q","all",&fp,serde_json::from_value(bad).unwrap()).is_err());}
